import { Book } from "@/lib/types";

export const ecclesiastes: Book = {
  id: "ecclesiastes",
  name: "Prediger",
  shortName: "Pred",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Worte des Predigers, des Sohnes Davids, des Königs in Jerusalem*.", heading: "Nichtigkeit alles Irdischen", footnotes: ["℘ V. 12; 1Kö 11,42; Spr 1,1"] },
      { number: 2, text: "Nichtigkeit der Nichtigkeiten*! — spricht der Prediger; Nichtigkeit der Nichtigkeiten, alles ist Nichtigkeit*!", footnotes: ["℘ Kap. 2,8", "℘ Röm 8,20"] },
      { number: 3, text: "Welchen Gewinn hat der Mensch von* all seinem Mühen, mit dem er sich abmüht unter der Sonne*?", footnotes: ["o. bei", "℘ Kap. 2,11.22; 3,9"] },
      { number: 4, text: "Eine Generation kommt*, und eine Generation geht; aber die Erde besteht in Ewigkeit*.", footnotes: ["w. wandelt", "℘ Ps 104,5; 2Petr 3,13; Offb 21,1"] },
      { number: 5, text: "Und die Sonne geht auf, und die Sonne geht unter, und sie strebt* ihrem Ort zu, wo sie wieder aufgeht*.", footnotes: ["w. lechzt", "℘ Ps 19,6.7"] },
      { number: 6, text: "Der Wind geht nach Süden und wendet sich nach Norden. Immer wieder sich wendend* geht er dahin, und zu seinem Ausgangspunkt* kehrt der Wind zurück*.", footnotes: ["w. sich wendend und wendend", "w. zu seinen Wendungen", "℘ Kap. 11,5"] },
      { number: 7, text: "Alle Flüsse gehen ins Meer, und das Meer wird nicht voll. An den Ort, wohin die Flüsse gehen, dorthin gehen sie immer wieder." },
      { number: 8, text: "Alle Worte mühen sich ab. Nichts vermag ein Mensch zu sagen.* Das Auge wird nicht satt zu sehen* und das Ohr nicht voll vom Hören.", footnotes: ["o. Alle Dinge mühen sich ab. Nicht aussprechen kann es ein Mensch.\n℘ Kap. 4,8; 6,7", "℘ Spr 27,20"] },
      { number: 9, text: "Das, was war, ist das, was wieder sein wird. Und das, was getan wurde, ist das, was wieder getan wird*. Und es gibt gar nichts Neues unter der Sonne.", footnotes: ["℘ Kap. 2,12; 3,15"] },
      { number: 10, text: "Gibt es ein Ding, von dem einer sagt: »Siehe, das ist neu«? Längst ist es gewesen für die Zeitalter*, die vor uns gewesen sind*.", footnotes: ["o. Ewigkeiten", "℘ Kap. 6,10"] },
      { number: 11, text: "Da gibt es keine Erinnerung an die Früheren. Und an die Künftigen, die sein werden, auch an sie wird man sich nicht mehr erinnern bei denen, die noch später sein werden*.", footnotes: ["℘ Kap. 2,16"] },
      { number: 12, text: "Ich, der Prediger, war König über Israel in Jerusalem*.", heading: "Nichtigkeit des Strebens nach Weisheit und Erkenntnis", footnotes: ["℘ V. 1"] },
      { number: 13, text: "Und ich richtete mein Herz darauf, in Weisheit alles zu erforschen und zu erkunden, was unter dem Himmel getan wird*. Ein übles Geschäft hat Gott da den Menschenkindern gegeben*, sich darin abzumühen*.", footnotes: ["℘ Spr 25,2", "℘ Kap. 4,8", "℘ Kap. 3,10"] },
      { number: 14, text: "Ich sah all die Taten, die unter der Sonne getan werden, und siehe, alles ist Nichtigkeit und ein Haschen nach Wind*.", footnotes: ["℘ Kap. 2,11.17.19.26; 3,19; 4,4.6.16; 6,9; 12,8"] },
      { number: 15, text: "Gekrümmtes kann nicht gerade werden, und Fehlendes kann nicht gezählt werden*.", footnotes: ["℘ Jer 13,23"] },
      { number: 16, text: "Ich sprach in* meinem Herzen* und sagte: Ich nun, siehe, ich habe die Weisheit vergrößert und vermehrt, mehr als jeder, der vor mir über Jerusalem* war, und mein Herz hat in Fülle Weisheit und Erkenntnis geschaut*.", footnotes: ["o. zu", "℘ Kap. 2,1.15; 3,17", "viele hebr. Handschr. und alte Üs.: in Jerusalem", "℘ 1Kö 5,9-11"] },
      { number: 17, text: "Auch richtete ich mein Herz darauf, Weisheit zu erkennen und Erkenntnis von Tollheit und Torheit zu haben*. Doch erkannte ich, dass auch das nur ein Haschen nach Wind ist*.", footnotes: ["℘ Kap. 2,12; 7,23.25; 8,16; Ps 73,16", "℘ Kap. 2,11.17.19.26; 3,19; 4,4.6.16; 6,9; 12,8"] },
      { number: 18, text: "Denn wo viel Weisheit ist, ist viel Verdruss, und wer Erkenntnis mehrt, mehrt Kummer*.", footnotes: ["℘ Kap. 12,12"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Ich sprach in meinem Herzen*: Auf denn, versuch es mit der Freude* und genieße das Gute*! Aber siehe, auch das ist Nichtigkeit*.", heading: "Nichtigkeit des Vergnügens und der Arbeit", footnotes: ["℘ Kap. 1,16", "w. ich will dich prüfen durch Freude\n℘ Kap. 8,15", "w. sieh auf das Gute", "℘ Lk 12,19.20"] },
      { number: 2, text: "Zum Lachen sprach ich: Unsinnig ist es! — und zur Freude: Was schafft die*?", footnotes: ["℘ Kap. 7,3; Spr 14,13; 17,22"] },
      { number: 3, text: "Ich beschloss in meinem Herzen*, meinen Leib durch Wein zu laben, während mein Herz sich mit Weisheit beschäftigte*, und die Torheit zu ergreifen, bis ich sähe, was den Menschenkindern zu tun gut wäre unter dem Himmel, die Zahl ihrer Lebenstage*.", footnotes: ["w. Ich spähte in meinem Herzen danach aus", "o. während mein Herz in Weisheit die Führung über mich behalten sollte", "℘ Kap. 6,12; Hebr 9,27"] },
      { number: 4, text: "Ich unternahm große Werke*: Ich baute mir Häuser*, ich pflanzte mir Weinberge*.", footnotes: ["℘ 2Chr 8,6", "℘ 1Kö 7,1.2", "℘ 1Chr 27,27"] },
      { number: 5, text: "Ich machte mir Gärten und Parks* und pflanzte darin die unterschiedlichsten Fruchtbäume*.", footnotes: ["o. Lustgärten; o. Paradiese", "w. Bäume von jeder Frucht"] },
      { number: 6, text: "Ich machte mir Wasserteiche, um daraus den aufsprießenden Wald von Bäumen zu bewässern." },
      { number: 7, text: "Ich kaufte Knechte und Mägde und hatte im Haus geborene Sklaven*. Auch hatte ich größeren Besitz an Rindern und Schafen* als alle, die vor mir in Jerusalem waren.", footnotes: ["w. Söhne des Hauses\n℘ Esr 2,58", "℘ 1Chr 27,29-31"] },
      { number: 8, text: "Ich sammelte mir auch Silber und Gold und Schätze* von Königen und Ländern. Ich beschaffte mir Sänger und Sängerinnen und die Vergnügungen der Menschenkinder: Frau und Frauen*.", footnotes: ["w. Eigentum\n℘ 1Kö 9,28", "d. i. viell. der Harem; die Wortbedeutung ist unsicher; LXX: Weinschenk und Weinschenken\n℘ 1Kö 11,3"] },
      { number: 9, text: "Und ich wurde größer und reicher als alle*, die vor mir in Jerusalem waren*. Dazu verblieb mir meine Weisheit.", footnotes: ["w. ich wurde groß und vermehrte mein Gut vor allen", "℘ 1Kö 10,23; 1Chr 29,25"] },
      { number: 10, text: "Und alles, was meine Augen begehrten, entzog ich ihnen nicht. Ich versagte meinem Herzen keine Freude, denn mein Herz hatte Freude von all meiner Mühe, und das war mein Teil von all meiner Mühe*.", footnotes: ["℘ V. 1.24; Kap. 8,15"] },
      { number: 11, text: "Und ich wandte mich hin zu all meinen Werken, die meine Hände gemacht, und zu der Mühe, mit der ich mich abgemüht hatte*. Und siehe, das alles war Nichtigkeit und ein Haschen nach Wind*. Also gibt es keinen Gewinn unter der Sonne*.", footnotes: ["w. die zu tun ich mich abgemüht hatte", "℘ V. 17.19; Kap. 1,14.17; 1Jo 2,17", "℘ Kap. 1,3.9"] },
      { number: 12, text: "Und ich wandte mich, um Weisheit und Tollheit und Torheit zu betrachten*. Denn was wird der Mensch tun, der nach dem König kommen wird? Das, was man schon längst getan hat*.", heading: "Bemühen um Weisheit ist nichtig wie um Torheit", footnotes: ["℘ Kap. 1,17", "℘ Kap. 1,9.10"] },
      { number: 13, text: "Und ich sah, dass die Weisheit den gleichen Vorzug vor der Torheit hat* wie das Licht vor der Finsternis*.", footnotes: ["℘ Spr 14,8", "w. gleich dem Vorzug des Lichts vor der Finsternis"] },
      { number: 14, text: "Der Weise hat seine Augen in seinem Kopf, der Tor aber geht in der Finsternis*. Doch erkannte ich auch, dass ein und dasselbe Geschick sie alle trifft*.", footnotes: ["℘ Mt 6,23", "℘ Kap. 6,8; 9,2; Ps 49,11"] },
      { number: 15, text: "Und ich sprach in meinem Herzen*: Gleich dem Geschick des Toren wird es auch mich treffen. Wozu bin ich dann so überaus weise gewesen? Und ich sprach in meinem Herzen, dass auch das Nichtigkeit ist.", footnotes: ["℘ Kap. 1,16"] },
      { number: 16, text: "Denn es gibt keine bleibende Erinnerung* an den Weisen, so wenig wie an den Toren, weil in den kommenden Tagen alles längst vergessen sein wird*. Und wie stirbt der Weise gleich dem Toren hin*!", footnotes: ["w. keine Erinnerung in Ewigkeit", "℘ Kap. 1,11", "℘ Spr 14,8"] },
      { number: 17, text: "Da hasste ich das Leben*, denn das Tun, das unter der Sonne getan wird, war mir zuwider*. Denn alles ist Nichtigkeit und ein Haschen nach Wind*. —", footnotes: ["℘ Hi 7,15.16", "w. übel lag auf mir das Tun, das unter der Sonne getan wird", "℘ V. 11"] },
      { number: 18, text: "Und ich hasste all mein Mühen, mit dem ich mich abmühte unter der Sonne. Ich muss es ja doch dem Menschen hinterlassen, der nach mir sein wird." },
      { number: 19, text: "Und wer weiß, ob der weise oder töricht sein wird? Und doch wird er Macht haben über all mein Mühen*, mit dem ich mich abgemüht habe und worin ich weise gewesen bin unter der Sonne. Auch das ist Nichtigkeit*.", footnotes: ["℘ 1Kö 11,43", "℘ V. 11"] },
      { number: 20, text: "Da wandte ich mich, mein Herz der Verzweiflung zu überlassen, wegen all dem Mühen, mit dem ich mich abgemüht hatte unter der Sonne." },
      { number: 21, text: "Denn da ist ein Mensch, dessen Mühen in Weisheit und in Erkenntnis und in Tüchtigkeit geschieht; und doch muss er sie einem Menschen als sein Teil abgeben, der sich nicht darum gemüht hat*. Auch das ist Nichtigkeit und ein großes Übel.", footnotes: ["℘ Ps 49,11"] },
      { number: 22, text: "Denn was bleibt dem Menschen von all seinem Mühen und vom Streben seines Herzens, womit er sich abmüht unter der Sonne*?", footnotes: ["℘ V. 11; Mt 16,26"] },
      { number: 23, text: "Denn all seine Tage sind Leiden*, und Verdruss ist sein Geschäft*; selbst nachts findet sein Herz keine Ruhe*. Auch das ist Nichtigkeit.", footnotes: ["o. Schmerzen; o. Kummer\n℘ Hi 5,7", "o. durch all seine Tage hin sind Leiden und Verdruss sein Geschäft", "w. sein Herz legt sich nicht schlafen\n℘ Kap. 8,16"] },
      { number: 24, text: "Es gibt nichts Besseres für den Menschen, als dass er isst und trinkt* und seine Seele Gutes sehen lässt bei seinem Mühen*. Auch das sah ich, dass dies alles aus der Hand Gottes kommt*.", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: Es gibt nichts Gutes bei dem Menschen, der isst und trinkt", "℘ 1Kö 4,20", "℘ V. 10; Kap. 3,12.13.22; 5,17"] },
      { number: 25, text: "Denn: »Wer kann essen und wer kann fröhlich sein* ohne mich*?«", footnotes: ["o. sich sorgen", "w. außerhalb von mir; d. h. ohne Gott; einige hebr. Handschr., LXX und die syr. Üs.: ohne ihn"] },
      { number: 26, text: "Denn dem Menschen, der vor ihm wohlgefällig ist, gibt er Weisheit und Erkenntnis* und Freude. Dem Sünder aber gibt er das Geschäft einzusammeln und aufzuhäufen, um es dem abzugeben, der vor Gott wohlgefällig ist*. Auch das ist Nichtigkeit und ein Haschen nach Wind*.", footnotes: ["℘ Spr 2,6", "℘ Hi 27,17", "℘ Kap. 1,14.17"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Für alles gibt es eine bestimmte Stunde*. Und für jedes Vorhaben unter dem Himmel gibt es eine Zeit*:", heading: "Wechselhaftigkeit menschlichen Lebens — Zufriedenheit durch Gottesfurcht", footnotes: ["w. Festsetzung", "℘ V. 17; Kap. 8,6; Jer 46,17"] },
      { number: 2, text: "Zeit fürs Gebären und Zeit fürs Sterben*, Zeit fürs Pflanzen* und Zeit fürs Ausreißen des Gepflanzten*,", footnotes: ["℘ Hi 14,5", "℘ Spr 24,27; Jes 28,24", "℘ Mt 13,30"] },
      { number: 3, text: "Zeit fürs Töten und Zeit fürs Heilen, Zeit fürs Abbrechen und Zeit fürs Bauen*,", footnotes: ["℘ Jes 6,10-12; Jer 1,10; Hag 1,2.4"] },
      { number: 4, text: "Zeit fürs Weinen und Zeit fürs Lachen*, Zeit fürs Klagen und Zeit fürs Tanzen*,", footnotes: ["℘ Kap. 7,14; Jes 40,1.2; Joh 16,22", "℘ Mt 9,15"] },
      { number: 5, text: "Zeit fürs Steinewerfen und Zeit fürs Steinesammeln, Zeit fürs Umarmen* und Zeit fürs sich Fernhalten vom Umarmen,", footnotes: ["℘ 1Kor 7,5"] },
      { number: 6, text: "Zeit fürs Suchen* und Zeit fürs Verlieren, Zeit fürs Aufbewahren und Zeit fürs Wegwerfen,", footnotes: ["℘ Lk 15,3-10"] },
      { number: 7, text: "Zeit fürs Zerreißen und Zeit fürs Zusammennähen, Zeit fürs Schweigen* und Zeit fürs Reden*,", footnotes: ["℘ 1Sam 10,16; 2Kö 18,36", "℘ Est 4,14; Hi 32,4; Apg 4,20"] },
      { number: 8, text: "Zeit fürs Lieben und Zeit fürs Hassen*, Zeit für Krieg und Zeit für Frieden*.", footnotes: ["℘ Ps 105,25", "℘ 2Kö 9,22"] },
      { number: 9, text: "Welchen Gewinn hat also der Schaffende bei dem, womit er sich abmüht*?", footnotes: ["℘ Kap. 1,3; Spr 14,23"] },
      { number: 10, text: "Ich habe das Geschäft gesehen, das Gott den Menschenkindern gegeben hat, sich darin abzumühen*.", footnotes: ["℘ Kap. 1,13"] },
      { number: 11, text: "Alles hat er schön* gemacht zu seiner Zeit*, auch hat er die Ewigkeit in ihr Herz gelegt, nur dass der Mensch das Werk nicht ergründet*, das Gott getan hat, vom Anfang bis zum Ende*.", footnotes: ["o. gut", "℘ 1Mo 1,31; Mk 7,37", "o. nicht herausfindet; o. nicht begreift; w. nicht findet", "℘ Kap. 8,17; 11,5; Röm 11,33"] },
      { number: 12, text: "Ich erkannte, dass es nichts Besseres bei ihnen* gibt, als sich zu freuen* und sich in seinem Leben gütlich zu tun*.", footnotes: ["d. h. den Menschen; manche lesen mit Textänderung: dass es für den Menschen nichts Besseres", "℘ V. 22; Kap. 8,15; 11,9", "o. in seinem Leben Gutes zu tun"] },
      { number: 13, text: "Aber auch, dass jeder Mensch isst und trinkt und Gutes sieht bei all seinem Mühen, das ist eine Gabe Gottes*.", footnotes: ["℘ Kap. 2,24; 5,18"] },
      { number: 14, text: "Ich erkannte, dass alles, was Gott tut, für ewig sein wird*. Es ist ihm nichts hinzuzufügen und nichts davon wegzunehmen*. Und Gott hat es so gemacht, damit man sich vor ihm fürchtet*.", footnotes: ["℘ Ps 33,11", "℘ 5Mo 32,4; 2Sam 22,31", "℘ Kap. 5,6; 12,13; Offb 15,4"] },
      { number: 15, text: "Was da ist, war längst, und was sein wird, ist längst gewesen*; und Gott sucht das Entschwundene wieder hervor.", footnotes: ["℘ Kap. 1,9.10"] },
      { number: 16, text: "Und ferner sah ich unter der Sonne: An dem Ort des Rechts*, dort war die Ungerechtigkeit*, und an dem Ort der Gerechtigkeit, dort war die Ungerechtigkeit*.", heading: "Rätselhaftigkeit des menschlichen Geschicks", footnotes: ["o. des Gesetzes; o. des Gerichts; o. der Rechtsprechung", "o. Gottlosigkeit", "o. Gottlosigkeit\n℘ Kap. 5,7; Ps 58,2.3; Jes 59,14"] },
      { number: 17, text: "Ich sprach in meinem Herzen*: Gott wird den Gerechten und den Ungerechten* richten*, denn es gibt eine Zeit* dort für jedes Vorhaben und für jedes Werk*.", footnotes: ["℘ Kap. 1,16", "o. den Gottlosen", "℘ Röm 2,6-8; 14,10.11; 2Thes 1,5-7", "o. denn er hat eine Zeit gesetzt", "℘ V. 1; Kap. 12,14; Apg 17,31; Offb 20,12"] },
      { number: 18, text: "Ich sprach in meinem Herzen: Der Menschenkinder wegen* ist es so, dass Gott sie prüft* und damit sie sehen*, dass sie nichts anderes als Vieh sind.", footnotes: ["w. der Sache der Menschenkinder wegen", "w. reinigend aussondert", "Andere üs. mit LXX, der koptischen und syr. Üs.: und damit er ihnen zeige"] },
      { number: 19, text: "Denn das Geschick der Menschenkinder und das Geschick des Viehs — sie haben ja ein und dasselbe Geschick* — ist dies: wie diese sterben, so stirbt jenes, und einen Odem* haben sie alle. Und einen Vorzug des Menschen vor dem Vieh gibt es nicht, denn alles ist Nichtigkeit*.", footnotes: ["℘ Ps 49,13", "o. Geist", "℘ Kap. 1,14.17"] },
      { number: 20, text: "Alles geht an einen Ort*. Alles ist aus dem Staub geworden, und alles kehrt zum Staub zurück*.", footnotes: ["℘ Kap. 6,6", "℘ 1Mo 3,19"] },
      { number: 21, text: "Wer kennt den Odem* der Menschenkinder, ob er nach oben steigt, und den Odem* des Viehs, ob er nach unten zur Erde hinabfährt*?", footnotes: ["o. Geist", "o. Geist", "℘ Hi 14,10.14"] },
      { number: 22, text: "Und ich sah, dass es nichts Besseres gibt, als dass der Mensch sich freut an* seinen Werken; denn das ist sein Teil*. Denn wer wird ihn dahin bringen, hineinzusehen in das, was nach ihm sein wird*?", footnotes: ["o. fröhlich ist bei", "℘ V. 12; Kap. 2,10.24", "℘ Kap. 6,12; 8,7; 10,14"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und ich wandte mich und sah all die Unterdrückungen, die unter der Sonne geschehen*. Und siehe, da waren Tränen der Unterdrückten*, und sie hatten keinen Tröster. Und von der Hand ihrer Unterdrücker ging Gewalttat aus*, und sie hatten keinen Tröster*.", heading: "Sinnlosigkeit des Lebens durch Unterdrückung, Eifersucht und Einsamkeit", footnotes: ["℘ Hi 24,12; Am 3,9.10", "o. Erpressten", "℘ 2Mo 5,18; Hi 9,24; 35,9", "℘ Ps 69,21; 142,5; Spr 29,2; Kla 1,16.17"] },
      { number: 2, text: "Da pries ich die Toten, die längst gestorben sind*, mehr als die Lebenden, die jetzt noch leben.", footnotes: ["℘ Kap. 7,1; Hi 3,17-22"] },
      { number: 3, text: "Und glücklicher als sie beide pries ich den, der noch nicht gewesen ist*, der das böse Tun nicht gesehen hat, das unter der Sonne geschieht.", footnotes: ["℘ Kap. 6,3.5; Hi 3,16"] },
      { number: 4, text: "Und ich sah all das Mühen und alle Tüchtigkeit bei der Arbeit, dass es Eifersucht des einen gegen den anderen ist*. Auch das ist Nichtigkeit und ein Haschen nach Wind*. —", footnotes: ["℘ 1Mo 4,4-8; 26,14; 31,1; 1Sam 18,9; Mt 20,11-15", "℘ Kap. 1,14.17"] },
      { number: 5, text: "Der Tor legt seine Hände ineinander und verzehrt sein eigenes Fleisch*. —", footnotes: ["℘ Spr 6,9-11"] },
      { number: 6, text: "Besser eine Hand voll Ruhe* als beide Fäuste voll Mühe und Haschen nach Wind*.", footnotes: ["℘ Spr 15,16", "℘ Kap. 1,14.17"] },
      { number: 7, text: "Und ich wandte mich und sah Nichtigkeit unter der Sonne:" },
      { number: 8, text: "Da ist einer allein und kein Zweiter bei ihm, auch hat er weder Sohn noch Bruder, und für all sein Mühen gibt es kein Ende*, auch werden seine Augen am Reichtum nicht satt*. Für wen mühe ich mich also* und lasse meine Seele Gutes entbehren? Auch das ist Nichtigkeit und ein übles Geschäft*.", footnotes: ["℘ Kap. 1,8", "℘ Kap. 5,9; Spr 27,20", "℘ Ps 39,7; Lk 12,20", "℘ Kap. 1,13"] },
      { number: 9, text: "Zwei sind besser daran als ein Einzelner*, weil sie einen guten Lohn für ihre Mühe haben.", footnotes: ["℘ 1Mo 2,18; Mk 6,7"] },
      { number: 10, text: "Denn wenn sie fallen, so richtet der eine seinen Gefährten auf. Wehe aber dem Einzelnen, der fällt, ohne dass ein Zweiter da ist, ihn aufzurichten!" },
      { number: 11, text: "Auch wenn zwei beieinander liegen, so wird ihnen warm*. Dem Einzelnen aber, wie soll ihm warm werden?", footnotes: ["℘ 1Kö 1,1.2"] },
      { number: 12, text: "Und wenn einer den Einzelnen überwältigt, so werden doch die zwei ihm widerstehen; und eine dreifache Schnur wird nicht so schnell zerrissen." },
      { number: 13, text: "Besser ein Junge, arm, aber weise, als ein König, alt, aber töricht, der es nicht versteht, sich warnen zu lassen.", heading: "Nichtigkeit der Volksgunst" },
      { number: 14, text: "Ja, aus dem Gefängnis* geht er hervor, um König zu werden*, obwohl er als Armer unter der Königsherrschaft jenes Königs geboren wurde*.", footnotes: ["so mit einigen hebr. Handschr. und den alten Üs.; w. Haus der Gefangenen; Mas. T.: Haus der Abgewichenen", "℘ 1Mo 41,14-43", "℘ 1Sam 2,8"] },
      { number: 15, text: "Ich sah alle Lebenden, die unter der Sonne leben*, mit dem Jungen, dem zweiten*, der an jenes Stelle treten sollte:", footnotes: ["w. gehen", "d. h. dem Thronanwärter"] },
      { number: 16, text: "endlos das ganze Volk, alle die, die er führte*. Doch auch über ihn werden sich die Späteren nicht freuen. Denn auch das ist Nichtigkeit und ein Haschen nach Wind*.", footnotes: ["w. kein Ende für alles Volk und für alle, vor denen er war", "℘ Kap. 1,14.17"] },
      { number: 17, text: "Bewahre deinen Fuß, wenn du zum Haus Gottes gehst*! Und: Herantreten, um zu hören, ist besser, als wenn die Toren Schlachtopfer geben*; denn sie sind Unwissende, so dass sie Böses tun*. —", heading: "Warnung vor Ehrfurchtslosigkeit gegenüber Gott", footnotes: ["℘ Jes 1,12", "℘ 1Sam 15,22; Spr 15,8; Jer 7,9-11", "w. denn Nicht-Erkennende sind sie, Böses zu tun"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Sei nicht vorschnell mit deinem Mund, und dein Herz eile nicht, ein Wort vor Gott hervorzubringen! Denn Gott ist im Himmel*, und du bist auf der Erde; darum seien deine Worte wenige*.", footnotes: ["℘ Hi 22,12", "℘ Spr 10,19; Mt 6,7"] },
      { number: 2, text: "Denn bei viel Geschäftigkeit kommt der Traum und bei vielen Worten törichte Rede*. —", footnotes: ["w. die Stimme des Toren\n℘ Kap. 10,12-14"] },
      { number: 3, text: "Wenn du Gott ein Gelübde ablegst, zögere nicht, es zu erfüllen! Denn er hat kein Gefallen an den Toren*. Was du gelobst, erfülle*!", footnotes: ["w. Denn kein Wohlgefallen ist an den Toren", "℘ 3Mo 27,2"] },
      { number: 4, text: "Besser, dass du nicht gelobst, als dass du gelobst und nicht erfüllst*.", footnotes: ["℘ Spr 20,25"] },
      { number: 5, text: "Gestatte deinem Mund nicht, dass er dein Fleisch in Sünde bringt*! Und sprich nicht vor dem Boten Gottes*: Es war ein Versehen*! Wozu soll Gott über deine Stimme zürnen und das Werk deiner Hände verderben?", footnotes: ["w. das Ziel verfehlen lässt", "℘ Mal 2,7", "w. unabsichtliches und unwissentliches Vergehen\n℘ 3Mo 5,4"] },
      { number: 6, text: "Denn bei vielen Träumen und Nichtigkeiten sind auch viele Worte*. So fürchte Gott*!", footnotes: ["o. Denn bei vielen Träumen sind auch Nichtigkeiten und viele Worte.\n℘ Kap. 10,12-14", "℘ Kap. 3,14; Spr 23,17"] },
      { number: 7, text: "Wenn du Unterdrückung des Armen und Raub von Recht und Gerechtigkeit im Land siehst, wundere dich nicht über die Sache*, denn ein Hoher wacht über dem anderen Hohen, und Hohe über ihnen beiden.", heading: "Nichtigkeit des Reichtums — Rat zu einfacher Lebensführung", footnotes: ["o. über das Vorhaben; o. über die Angelegenheit\n℘ Kap. 3,16; 8,9; 1Petr 4,12"] },
      { number: 8, text: "Doch ein Gewinn für das Land ist bei alldem dies: Ein König, der für das bebaute Feld sorgt*.", footnotes: ["℘ 2Chr 26,10"] },
      { number: 9, text: "Wer Geld liebt, wird des Geldes nicht satt, und wer den Reichtum liebt, nicht des Ertrages*. Auch das ist Nichtigkeit. —", footnotes: ["℘ Kap. 4,8; 6,7"] },
      { number: 10, text: "Wenn das Gut sich mehrt, so mehren sich die, die davon zehren. Und welchen Nutzen hat sein Besitzer, als dass seine Augen es ansehen*? —", footnotes: ["w. als das Sehen seiner Augen"] },
      { number: 11, text: "Süß ist der Schlaf des Arbeiters, ob er wenig oder viel isst; aber der Überfluss* des Reichen lässt ihn nicht schlafen. —", footnotes: ["w. die Sättigung"] },
      { number: 12, text: "Es gibt ein schlimmes* Übel, das ich unter der Sonne gesehen habe: Reichtum, der von seinem Besitzer zu seinem Unglück aufbewahrt wird.", footnotes: ["w. ein krankes"] },
      { number: 13, text: "Und geht solcher Reichtum durch ein unglückliches Ereignis* verloren* und hat er einen Sohn gezeugt, so ist gar nichts in dessen Hand.", footnotes: ["w. Geschäft", "℘ Spr 23,4.5; 27,24"] },
      { number: 14, text: "Wie er aus dem Leib seiner Mutter hervorgekommen ist, nackt wird er wieder hingehen, wie er gekommen ist, und für seine Mühe wird er nicht das Geringste davontragen, das er in seiner Hand mitnehmen könnte*.", footnotes: ["℘ Hi 1,21; Ps 49,18; 1Tim 6,7"] },
      { number: 15, text: "Und auch dies ist ein schlimmes* Übel: Ganz wie er gekommen ist, wird er hingehen. Und was für einen Gewinn hat er davon, dass er für den Wind sich müht*?", footnotes: ["w. ein krankes", "℘ Hos 12,2"] },
      { number: 16, text: "Auch isst er all seine Tage in Finsternis* und hat viel Verdruss und Krankheit* und Zorn.", footnotes: ["LXX, die koptische und eine syr. Üs. lesen: Auch sind alle seine Tage in Finsternis und Trauer", "so die alten Üs.; Mas. T.: seine Krankheit"] },
      { number: 17, text: "Siehe, was ich als gut, was ich als schön erkannt habe: Dass einer isst und trinkt und Gutes sieht bei all seiner Mühe, mit der er sich abmüht unter der Sonne, die Zahl seiner Lebenstage, die Gott ihm gegeben hat; denn das ist sein Teil*.", footnotes: ["℘ Kap. 2,10.24; 7,14"] },
      { number: 18, text: "Auch jeder Mensch, dem Gott Reichtum und Güter* gegeben und den er ermächtigt hat, davon zu genießen* und sein Teil zu nehmen und sich bei seiner Mühe zu freuen — das ist eine Gabe Gottes*.", footnotes: ["o. Vermögen; o. Schätze", "w. zu essen", "℘ Kap. 3,13"] },
      { number: 19, text: "Denn er denkt nicht viel an die Tage seines Lebens, weil Gott ihn mit der Freude seines Herzens beschäftigt*.", footnotes: ["℘ Kap. 6,2"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Es gibt ein Übel, das ich unter der Sonne gesehen habe, und schwer lastet es auf dem Menschen:", heading: "Nichtigkeit von Reichtum und Ehre" },
      { number: 2, text: "Ein Mensch, dem Gott Reichtum und Güter* und Ehre gibt, und seiner Seele fehlt nichts von allem, was er wünschen mag*; aber Gott ermächtigt ihn nicht, davon zu genießen*, sondern ein fremder Mann genießt* es. Das ist Nichtigkeit und ein schlimmes Übel*. —", footnotes: ["o. Vermögen; o. Schätze", "℘ Kap. 5,18.19", "w. zu essen\n℘ Lk 12,20", "w. isst", "w. eine böse Krankheit"] },
      { number: 3, text: "Wenn ein Mann hundert Kinder zeugte und viele Jahre lebte, dass die Tage seiner Jahre viele wären, aber seine Seele sich nicht am Guten sättigte, und ihm auch kein Begräbnis zuteil würde*, von dem sage ich: Eine Fehlgeburt ist besser daran als er*.", footnotes: ["℘ 2Kö 9,35; Jer 36,30", "℘ Kap. 4,3; Hi 3,11"] },
      { number: 4, text: "Denn in Nichtigkeit kommt sie, und in Finsternis geht sie dahin, und mit Finsternis wird ihr Name bedeckt;" },
      { number: 5, text: "auch hat sie die Sonne nicht gesehen und nicht gekannt. Diese hat mehr Ruhe als jener*.", footnotes: ["℘ Kap. 4,3; Hi 3,11"] },
      { number: 6, text: "Und wenn er auch zweimal tausend Jahre gelebt, aber Gutes nicht gesehen hätte, — geht nicht alles an einen Ort*?", footnotes: ["℘ Kap. 3,20"] },
      { number: 7, text: "Alles Mühen des Menschen ist für seinen Mund*, und doch wird seine Begierde nicht gestillt*.", footnotes: ["℘ Kap. 1,8; Spr 16,26", "w. wird seine Seele nicht gefüllt\n℘ Kap. 5,9; Joh 4,13"] },
      { number: 8, text: "Denn was für einen Vorzug hat der Weise vor dem Toren*? Was nützt es dem Demütigen*, der es versteht, vor den Lebenden recht zu wandeln?", footnotes: ["℘ Kap. 2,14-16", "o. dem Elenden"] },
      { number: 9, text: "Besser das Sehen mit den Augen als das Umherschweifen der Begierde*! Auch das ist Nichtigkeit und ein Haschen nach Wind*.", footnotes: ["w. als das Gehen der Seele", "℘ Kap. 1,14.17"] },
      { number: 10, text: "Was geschieht, schon längst ist sein Name genannt*, und bekannt ist, was ein Mensch sein wird. Darum kann er* nicht mit dem rechten, der stärker ist als er*.", footnotes: ["℘ Kap. 1,9-11", "o. darf er", "℘ Hi 9,32; Jes 45,9"] },
      { number: 11, text: "Denn da sind viele Worte*, die die Nichtigkeit nur größer machen. — Welchen Nutzen hat der Mensch davon?", footnotes: ["o. Reden"] },
      { number: 12, text: "Denn wer erkennt, was für den Menschen im Leben gut ist, die Zahl der Tage seines nichtigen Lebens, die er wie ein Schatten verbringt*? Denn wer kann dem Menschen mitteilen, was nach ihm sein wird unter der Sonne*?", footnotes: ["w. und er macht sie wie einen Schatten\n℘ Kap. 2,3; 1Chr 29,15", "℘ Kap. 3,22"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Besser ein guter Name* als gutes Salböl* und der Tag des Todes als der Tag, da einer geboren wird*.", heading: "Mahnung zur Anerkennung göttlicher Führungen, zu einem guten Mittelweg und zu echter Weisheit", footnotes: ["℘ Spr 25,10", "℘ Spr 22,1", "℘ Kap. 4,2; Offb 14,13"] },
      { number: 2, text: "Besser, ins Haus der Trauer zu gehen, als ins Haus des Gastmahls zu gehen; denn jenes ist das Ende aller Menschen*, und der Lebende nimmt es sich zu Herzen*. —", footnotes: ["℘ Hebr 9,27", "℘ Kap. 9,5; Ps 90,12"] },
      { number: 3, text: "Besser Verdruss als Lachen; denn bei traurigem Gesicht ist das Herz in rechter Verfassung*. —", footnotes: ["w. ist das Herz fröhlich\n℘ Kap. 2,2"] },
      { number: 4, text: "Das Herz der Weisen ist im Haus der Trauer, das Herz der Toren aber im Haus der Freude." },
      { number: 5, text: "Besser, das Schelten* des Weisen zu hören*, als dass einer das Singen der Toren hört.", footnotes: ["o. Drohen; o. Zurechtweisen", "℘ Ps 141,5; Spr 15,31"] },
      { number: 6, text: "Denn wie das Prasseln der Dornen unter dem Kochtopf* so das Lachen des Toren. Auch das ist Nichtigkeit.", footnotes: ["℘ Ps 118,12"] },
      { number: 7, text: "Ja, unrechter Gewinn macht den Weisen zum Toren, und das Bestechungsgeschenk richtet das Herz zugrunde*.", footnotes: ["℘ 2Mo 23,8"] },
      { number: 8, text: "Besser das Ende einer Sache als ihr Anfang, besser langmütig als hochmütig*.", footnotes: ["w. ein langer Atem als ein hoher, stolzer Atem\n℘ Spr 14,29"] },
      { number: 9, text: "Sei nicht vorschnell in deinem Geist zum Zorn*, denn der Zorn ruht im Busen* der Toren.", footnotes: ["℘ Spr 16,32; 25,8; Jon 4,3.8; Eph 4,26.27; Jak 1,19", "o. im Schoß"] },
      { number: 10, text: "Sage nicht: Wie kommt es, dass die früheren Tage besser waren als diese? Denn nicht aus Weisheit fragst du danach." },
      { number: 11, text: "Gut ist Weisheit zusammen mit Erbbesitz und ein Vorteil für die, die die Sonne sehen*.", footnotes: ["℘ Hi 28,12-19; Ps 119,72; Spr 3,14.15"] },
      { number: 12, text: "Denn im Schatten der Weisheit ist es wie im Schatten des Geldes; aber der Gewinn der Erkenntnis ist der: Die Weisheit erhält ihren Besitzer am Leben*.", footnotes: ["℘ Spr 8,35"] },
      { number: 13, text: "Sieh das Werk Gottes an*! Ja, wer kann gerade machen, was er gekrümmt hat*?", footnotes: ["℘ Hi 37,14", "℘ Hi 12,14"] },
      { number: 14, text: "Am Tag des Glücks* sei guter Dinge*! Und am Tag des Unglücks bedenke*: Auch diesen hat Gott ebenso wie jenen gemacht*; gerade deshalb, weil der Mensch gar nichts herausfinden kann von dem, was nach ihm ist.", footnotes: ["w. des Guten", "℘ Kap. 3,4; 5,17; 11,9", "w. sieh", "℘ Hi 2,10; Kla 3,38"] },
      { number: 15, text: "Das alles habe ich gesehen in den Tagen meiner Nichtigkeit! Da ist ein Gerechter, der bei seiner Gerechtigkeit umkommt, und da ist ein Ungerechter*, der bei seiner Bosheit seine Tage verlängert*.", footnotes: ["o. Gottloser", "℘ Kap. 8,14; Hi 21,7-13; Ps 10,3-6; 73,3"] },
      { number: 16, text: "Sei nicht allzu gerecht und gebärde dich nicht übermäßig weise! Wozu willst du dich zugrunde richten?" },
      { number: 17, text: "Sei nicht allzu ungerecht* und sei kein Tor! Wozu willst du sterben, ehe deine Zeit da ist*?", footnotes: ["o. gottlos", "℘ Ps 55,24; Spr 10,27"] },
      { number: 18, text: "Es ist gut, dass du an diesem festhältst und auch von jenem deine Hand nicht lässt, denn der Gottesfürchtige entgeht dem allen*.", footnotes: ["℘ Spr 12,21"] },
      { number: 19, text: "Die Weisheit hilft den Weisen mehr als zehn Machthaber, die in der Stadt sind*.", footnotes: ["℘ Kap. 9,15-18; 2Sam 20,22; Spr 8,14; 21,22"] },
      { number: 20, text: "Denn kein Mensch auf Erden ist so gerecht, dass er nur Gutes täte und niemals sündigte*.", footnotes: ["℘ 1Kö 8,46; Ps 14,3; 143,2; Röm 3,12.23; Jak 3,2"] },
      { number: 21, text: "Auch richte dein Herz nicht auf all die Worte, die man redet, damit du nicht hörst, wie dein Knecht* dich verflucht*;", footnotes: ["o. Sklave", "℘ 1Sam 10,27"] },
      { number: 22, text: "denn auch viele Male — dein Herz weiß es — hast auch du andere verflucht*.", footnotes: ["℘ Jak 3,9"] },
      { number: 23, text: "Das alles habe ich in Weisheit geprüft. Ich sprach: Ich will weise werden, aber sie* blieb fern von mir.", footnotes: ["d. h. die Weisheit"] },
      { number: 24, text: "Fern ist, was da ist, und tief, tief! Wer kann es ergründen*?", footnotes: ["w. Wer kann dahin gelangen?\n℘ Hi 28,12"] },
      { number: 25, text: "Ich wandte mich, und mein Herz ging darauf aus, Weisheit und ein richtiges Urteil* zu erkennen und zu erkunden und zu suchen und Ungerechtigkeit* als Torheit und die Narrheit als Tollheit zu erkennen*.", footnotes: ["w. Denkergebnis", "o. Gottlosigkeit", "℘ Kap. 1,17"] },
      { number: 26, text: "Und ich fand bitterer als den Tod die Frau, die Netzen gleich ist und deren Herz Fangstricke*, deren Hände Fesseln sind*. Wer vor Gott angenehm ist, wird ihr entrinnen, der Sünder aber wird durch sie gefangen*.", footnotes: ["w. Schleppnetze", "℘ Spr 2,19; 5,3-5; 23,28", "℘ 1Mo 39,9; Ri 16,19; Spr 22,14"] },
      { number: 27, text: "Siehe, dies fand ich, spricht der Prediger, indem ich eins zum anderen fügte, um ein richtiges Urteil* zu finden:", footnotes: ["w. Denkergebnis"] },
      { number: 28, text: "Was meine Seele fortwährend suchte und ich nicht fand: Einen Mann fand ich aus Tausenden, aber eine Frau unter diesen allen fand ich nicht." },
      { number: 29, text: "Allein, siehe, dies habe ich gefunden: Gott hat den Menschen aufrichtig* gemacht; sie aber suchten viele Künste*.", footnotes: ["w. gerade", "℘ Hes 28,15; Röm 1,21-32"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Wer ist wie der Weise, und wer versteht* die Deutung der Dinge*? Die Weisheit des Menschen lässt sein Gesicht leuchten, und die Härte seines Gesichts verändert sich.", footnotes: ["o. erkennt", "w. der Sache; o. des Wortes\n℘ Dan 2,22"] },
      { number: 2, text: "Ich sage: Dem Befehl* des Königs gehorche*, und zwar wegen des Eides Gottes*!", heading: "Verhalten zur Obrigkeit", footnotes: ["w. Dem Mund", "℘ Spr 24,21; Röm 13,5", "℘ 1Sam 14,26"] },
      { number: 3, text: "Übereile dich nicht, von ihm wegzugehen*, lass dich nicht auf eine böse Sache ein*! Er tut ja doch alles, was er will*.", footnotes: ["o. gehorche, aber wenn du einen Gotteseid schwören sollst, 3 übereile dich nicht! Geh weg von seinem Angesicht\n℘ Kap. 10,4", "o. bestehe nicht auf einer üblen Sache\n℘ Spr 24,21; Röm 13,5", "℘ Dan 5,19"] },
      { number: 4, text: "Denn des Königs Wort ist mächtig*, und wer will zu ihm sagen: Was tust du da?", footnotes: ["℘ 2Sam 24,4; 1Kö 1,30; Esr 6,13"] },
      { number: 5, text: "Wer das Gebot hält, weiß um keine böse Sache, und das Herz eines Weisen kennt die richtige Zeit und das rechte Verhalten*.", footnotes: ["o. das angemessene Gerichtsurteil; o. die sachgemäße Entscheidung"] },
      { number: 6, text: "Denn für jede Sache gibt es die richtige Zeit* und das rechte Verhalten*. Denn das Unglück des Menschen lastet schwer* auf ihm*,", footnotes: ["℘ Kap. 3,1", "o. das angemessene Gerichtsurteil; o. die sachgemäße Entscheidung", "o. Denn das Böse des Menschen wird groß", "℘ Hi 33,17-19"] },
      { number: 7, text: "denn er weiß nicht, was werden wird; denn wer sollte ihm mitteilen, wie es werden wird*?", footnotes: ["℘ Kap. 3,22; 9,1; Est 5,12; Spr 27,1"] },
      { number: 8, text: "Kein Mensch hat Gewalt über den Wind*, den Wind* zurückzuhalten, und niemand hat Gewalt über den Tag des Todes*. Auch gibt es keine Entlassung im Krieg, und das Unrecht* rettet nicht seinen Herrn*.", footnotes: ["o. Geist", "o. Geist", "℘ Kap. 9,12; Hi 14,5", "o. Gottlosigkeit. — Bei Umstellung von zwei Buchstaben: der Reichtum", "o. Besitzer; d. h. den, der Unrecht tut\n℘ Spr 12,3; Jes 47,10"] },
      { number: 9, text: "Das alles sah ich und richtete mein Herz auf alles Tun, das unter der Sonne getan wird, zur Zeit, da der Mensch über den Menschen Gewalt hat zu seinem Unglück*.", footnotes: ["o. Bösen; o. Schaden\n℘ Kap. 5,7"] },
      { number: 10, text: "Und so sah ich Ungerechte*, die begraben wurden und zur Ruhe eingingen. Die aber das Rechte getan hatten, mussten von der heiligen Stätte wegziehen und wurden in der Stadt vergessen. Auch das ist Nichtigkeit.", heading: "Unbegreifliches gleiches Ergehen der Gerechten und Gottlosen — Gleiches Los für alle", footnotes: ["o. Gottlose"] },
      { number: 11, text: "Weil der Urteilsspruch über die böse Tat nicht schnell vollzogen wird, darum ist das Herz der Menschenkinder davon* erfüllt, Böses zu tun*,", footnotes: ["w. in ihnen davon", "℘ Kap. 9,3; Ps 10,4-11; Jes 26,10; Mt 24,48"] },
      { number: 12, text: "denn ein Sünder tut hundertmal Böses und verlängert doch seine Tage*. Aber ich habe auch erkannt, dass es den Gottesfürchtigen gut gehen wird, die sich vor seinem Angesicht fürchten*.", footnotes: ["℘ Hi 35,15", "℘ 2Mo 1,20; Ps 112,1; 115,13; Spr 28,14"] },
      { number: 13, text: "Doch nicht gut gehen wird es dem Ungerechten*, und er wird, dem Schatten gleich, seine Tage nicht verlängern*, weil er sich vor dem Angesicht Gottes nicht fürchtet.", footnotes: ["o. Gottlosen\n℘ Mal 3,19.20", "℘ Ps 37,1.2; Jes 65,20; Jer 44,10"] },
      { number: 14, text: "Es gibt etwas Nichtiges, das auf Erden geschieht: Da sind Gerechte, denen es nach dem Tun der Ungerechten* ergeht, und da sind Ungerechte*, denen es nach dem Tun der Gerechten ergeht*. Ich sagte: Auch das ist Nichtigkeit.", footnotes: ["o. Gottlosen", "o. Gottlose", "℘ Kap. 7,15; Hi 1,22; Jer 12,1; Mal 3,15"] },
      { number: 15, text: "Und ich pries die Freude, weil es für den Menschen nichts Besseres unter der Sonne gibt, als zu essen und zu trinken und sich zu freuen*. Und dies wird* ihn begleiten bei seinem Mühen die Tage seines Lebens hindurch, die Gott ihm unter der Sonne gegeben hat.", footnotes: ["℘ Kap. 2,1.10; 3,12; 9,7", "o. möge; o. kann"] },
      { number: 16, text: "Als ich mein Herz darauf richtete, Weisheit zu erkennen und das Treiben zu besehen, das auf Erden geschieht* — denn weder bei Tag noch bei Nacht sieht man Schlaf mit seinen Augen* —,", footnotes: ["℘ Kap. 1,17", "℘ Kap. 2,23"] },
      { number: 17, text: "da sah ich am Ganzen des Werkes Gottes, dass der Mensch das Werk nicht ergründen* kann, das unter der Sonne geschieht. Wie sehr der Mensch sich auch abmüht, es zu erforschen*, so ergründet* er es nicht*. Und selbst wenn der Weise behauptet*, es zu erkennen, er kann es doch nicht ergründen*.", footnotes: ["w. erreichen, o. finden", "w. suchen", "w. erreicht, o. findet", "℘ Ps 73,16", "o. meint; w. sagt", "o. meint; w. sagt\n℘ Kap. 3,11"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Denn das alles habe ich mir zu Herzen genommen, und zwar um dies alles zu prüfen*: dass die Gerechten und die Weisen und ihre Taten in der Hand Gottes sind. Sei es Liebe, sei es Hass, nichts davon erkennt der Mensch. *Alles beides liegt vor ihrer Zeit*,", footnotes: ["LXX: und mein Herz sah dies alles", "Andere üs. in Anlehnung an LXX: Alles, was vor ihnen in der Zukunft liegt, ist Nichtigkeit", "w. vor ihnen; aram. Üs.: Alles ist ihnen vorherbestimmt\n℘ Kap. 8,7"] },
      { number: 2, text: "alles beides* — wie bei allen Menschen. Ein Geschick ist für den Gerechten und für den Ungerechten* bestimmt, für den Guten und den Reinen und den Unreinen und für den, der opfert, und den, der nicht opfert; wie der Gute, so der Sünder, der, der schwört, wie der, der den Eid scheut*.", footnotes: ["Andere üs. in Anlehnung an LXX: Alles, was vor ihnen in der Zukunft liegt, ist Nichtigkeit", "o. Gottlosen", "℘ Kap. 2,14-16; Hi 9,22; 21,26"] },
      { number: 3, text: "Das ist ein Übel in allem, was unter der Sonne geschieht, dass einerlei Geschick allen zuteil wird*. Auch ist das Herz der Menschenkinder voll Bosheit*, und Irrsinn ist in ihrem Herzen während ihres Lebens*; und danach* geht es zu den Toten*.", footnotes: ["℘ Kap. 2,14-16; Hi 9,22; 21,26", "℘ Kap. 8,11; 1Mo 6,5", "℘ Ps 64,7", "d. h. nach dem Leben", "℘ V. 11"] },
      { number: 4, text: "Ja, wer noch all den Lebenden zugesellt ist, für den gibt es Hoffnung. Denn selbst ein lebendiger Hund ist besser daran als ein toter Löwe!" },
      { number: 5, text: "Denn die Lebenden wissen, dass sie sterben werden*, die Toten aber wissen gar nichts*, und sie haben keinen Lohn mehr, denn ihr Name* ist vergessen*.", footnotes: ["℘ Kap. 7,2; 2Sam 14,14; Hi 30,23", "℘ Hi 14,21; Jes 63,16", "w. ihre Namensnennung", "℘ Ps 88,13"] },
      { number: 6, text: "Auch ihr Lieben, auch ihr Hassen, auch ihr Eifern ist längst verloren gegangen*. Und sie haben ewig keinen Anteil mehr an allem, was unter der Sonne geschieht*.", footnotes: ["℘ Hi 3,17-19; Ps 146,4", "℘ Jes 38,11"] },
      { number: 7, text: "Geh hin, iss dein Brot mit Freude und trink deinen Wein mit frohem Herzen*! Denn längst hat Gott Wohlgefallen an deinem Tun.", heading: "Freude am Leben bei Ohnmacht gegenüber der Zeit", footnotes: ["℘ Kap. 8,15; Rt 3,7"] },
      { number: 8, text: "Deine Kleider seien weiß* zu jeder Zeit, und das Salböl fehle nicht auf deinem Haupt.", footnotes: ["℘ Offb 3,4.5; 19,8"] },
      { number: 9, text: "Genieße* das Leben mit der Frau, die du liebst*, alle Tage deines nichtigen Lebens, das er dir unter der Sonne gegeben hat, all deine nichtigen Tage hindurch! Denn das ist dein Anteil am Leben und an deinem Mühen, womit du dich abmühst unter der Sonne.", footnotes: ["w. Sieh auf", "℘ 1Mo 26,8; Spr 5,18"] },
      { number: 10, text: "Alles, was deine Hand zu tun findet, das tue* in deiner Kraft*! Denn es gibt weder Tun noch Berechnung, noch Kenntnis, noch Weisheit im Scheol, in den du gehst*.", footnotes: ["℘ 1Sam 10,7; Spr 3,28; 1Kor 15,58", "o. Alles, was deine Hand zu tun findet in deiner Kraft, das tue", "℘ Hi 10,21.22; Jes 38,18"] },
      { number: 11, text: "Ferner sah ich* unter der Sonne, dass nicht die Schnellen den Lauf gewinnen und nicht die Helden den Krieg* und auch nicht die Weisen das Brot und auch nicht die Verständigen den Reichtum und auch nicht die Kenntnisreichen die Beliebtheit, sondern Zeit und Geschick trifft sie alle*.", footnotes: ["w. Ich wandte mich um und sah", "w. dass nicht den Schnellen der Lauf ist und nicht den Helden der Krieg usw.\n℘ Ps 33,16; Jer 46,6; Am 2,14-16", "℘ V. 3"] },
      { number: 12, text: "Denn auch kennt der Mensch seine Zeit nicht*. Wie die Fische, die gefangen werden im verderblichen Netz*, und wie die Vögel, die in der Falle gefangen werden, wie sie werden die Menschenkinder verstrickt zur Zeit des Unglücks, wenn es plötzlich über sie fällt*.", footnotes: ["℘ Kap. 8,8", "℘ Hes 32,3; Hos 7,12", "℘ Ps 73,19; Spr 24,22; Lk 21,35; 1Thes 5,3"] },
      { number: 13, text: "Auch dieses sah ich als Weisheit unter der Sonne, und es* kam mir groß vor:", heading: "Weisheit und Torheit", footnotes: ["w. sie"] },
      { number: 14, text: "Es war eine kleine Stadt, und wenig Männer waren darin. Gegen die kam ein großer König, umzingelte sie und baute große Belagerungswerke gegen sie*.", footnotes: ["℘ 2Sam 20,15"] },
      { number: 15, text: "Aber es fand sich darin ein armer weiser Mann, der die Stadt durch seine Weisheit hätte retten können*, aber kein Mensch dachte an diesen armen Mann*.", footnotes: ["w. rettete", "℘ 1Mo 40,23"] },
      { number: 16, text: "Da sagte ich mir: »Weisheit ist besser als Stärke*!« Aber die Weisheit des Armen wird verachtet, und seine Worte werden nicht gehört*. —", footnotes: ["℘ Kap. 7,19; 10,10", "℘ Mk 6,2.3"] },
      { number: 17, text: "Worte der Weisen, in Ruhe gehört, sind mehr wert als das Geschrei des Herrschers unter Toren." },
      { number: 18, text: "Weisheit ist besser als Kriegsgerät*, aber ein Sünder verdirbt* viel Gutes*.", footnotes: ["℘ Kap. 7,19; 10,10", "w. richtet . . . zugrunde", "℘ Kap. 10,1; Jos 7,1"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Tote Fliegen* lassen das Öl des Salbenmischers stinken und gären*. Ein wenig Torheit hat mehr Gewicht als Weisheit und Ehre*. —", footnotes: ["o. giftige Fliegen; w. Fliegen des Todes", "℘ Hag 2,12.13; Gal 5,9", "o. Kostbarer als Weisheit und als Ehre ist ein wenig Torheit\n℘ Kap. 9,18"] },
      { number: 2, text: "Der Verstand* des Weisen ist zu seiner Rechten und der Verstand* des Toren zu seiner Linken*.", footnotes: ["w. Das Herz", "w. Das Herz", "℘ Spr 15,7"] },
      { number: 3, text: "Und auch wenn der Tor auf dem Weg geht, fehlt ihm der Verstand*, und er sagt jedem, er sei ein Tor*.", footnotes: ["w. Das Herz", "d. h. er trägt seine Torheit zur Schau, o. er bezeichnet alle anderen als Toren\n℘ Spr 13,16"] },
      { number: 4, text: "Wenn der Zorn* des Herrschers gegen dich aufsteigt, so verlass deinen Platz nicht*! Denn Gelassenheit verhindert* große Sünden*. —", footnotes: ["w. der Geist", "℘ Kap. 8,3", "w. lässt liegen", "℘ Spr 25,15"] },
      { number: 5, text: "Es gibt ein Übel, das ich unter der Sonne gesehen habe, gleich einem Versehen, das vom Machthaber ausgeht:" },
      { number: 6, text: "Die Torheit* wird in große Würden eingesetzt*, und Reiche sitzen in Niedrigkeit.", footnotes: ["LXX: Der Tor", "w. auf große Höhen gestellt"] },
      { number: 7, text: "Ich habe Knechte auf Pferden gesehen* und Oberste, die wie Knechte zu Fuß* gingen.", footnotes: ["℘ Spr 19,10", "w. auf der Erde"] },
      { number: 8, text: "Wer eine Grube gräbt, kann hineinfallen*, und wer eine Mauer einreißt, den kann eine Schlange beißen*.", footnotes: ["℘ Ps 7,16", "℘ Spr 26,27; Am 5,19"] },
      { number: 9, text: "Wer Steine bricht, kann sich an ihnen verletzen, wer Holz spaltet, kann sich an ihm gefährden. —" },
      { number: 10, text: "Wenn das Eisen stumpf geworden ist und niemand die Schneide schleift, so muss man seine Kräfte mehr anstrengen. Aber ein Vorteil ist es, die Weisheit richtig anzuwenden*. —", footnotes: ["o. So ist es ein Vorteil, wenn die Weisheit etwas tauglich macht\n℘ Kap. 9,16"] },
      { number: 11, text: "Wenn die Schlange vor der Beschwörung beißt, so hat der Beschwörer* keinen Vorteil*.", footnotes: ["w. Herr der Zunge", "℘ Ps 58,6"] },
      { number: 12, text: "Die Worte aus dem Mund eines Weisen bringen ihm Beliebtheit*, aber die Lippen eines Toren verschlingen ihn selbst*.", footnotes: ["℘ Spr 10,32; Lk 4,22", "℘ Spr 10,8"] },
      { number: 13, text: "Der Anfang der Worte seines Mundes ist Torheit und das Ende seiner Rede* böser Unsinn*.", footnotes: ["w. seines Mundes", "℘ Kap. 5,2.6; Spr 13,16"] },
      { number: 14, text: "Und der Tor macht viele Worte. Der Mensch erkennt nicht, was sein wird. Und was nach ihm sein wird, wer teilt es ihm mit*?", footnotes: ["℘ Kap. 3,22"] },
      { number: 15, text: "Die Arbeit* des Toren macht ihn müde, ihn, der nicht zur Stadt zu gehen weiß.", footnotes: ["o. Mühe"] },
      { number: 16, text: "Wehe dir, Land, dessen König ein Junge ist* und dessen Oberste schon am Morgen speisen*!", footnotes: ["℘ 1Kö 12,11; Jes 3,4.12", "℘ Jes 5,11"] },
      { number: 17, text: "Glücklich du Land, dessen König ein Edler* ist* und dessen Oberste zur rechten Zeit speisen, als Männer und nicht als Zecher*! —", footnotes: ["w. ein Sohn der Freigeborenen", "℘ Spr 31,4.5", "w. in Kraft und nicht im Trinken"] },
      { number: 18, text: "Durch Faulheit der beiden Hände* senkt sich das Gebälk, und durch Lässigkeit* der Hände tropft das Haus*. —", footnotes: ["o. Durch doppelte Faulheit", "w. durch das Sinkenlassen", "℘ Spr 23,21"] },
      { number: 19, text: "Um zu lachen, bereitet man ein Mahl*, und Wein erheitert das Leben*, und das Geld gewährt* das alles. —", footnotes: ["℘ Ri 14,10", "℘ Est 1,10; Ps 104,15", "w. antwortet auf"] },
      { number: 20, text: "Auch in deinen Gedanken fluche nicht dem König* und in deinen Schlafzimmern fluche nicht über den Reichen! Denn die Vögel des Himmels könnten die Stimme entführen und was Flügel hat*, das Wort anzeigen*.", footnotes: ["℘ 2Mo 22,27; 1Petr 2,17", "w. der Herr des Flügelpaars", "℘ Lk 12,2.3"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Wirf dein Brot hin auf die Wasserfläche!* — denn du wirst* es nach vielen Tagen wieder finden! —", heading: "Nützliches Handeln in der Gegenwart bei ungewisser Zukunft", footnotes: ["℘ Jes 32,20", "o. dennoch wirst du"] },
      { number: 2, text: "Gib Anteil sieben anderen, ja, sogar acht, denn du weißt nicht*, was für Unglück sich auf der Erde ereignen wird*! —", footnotes: ["o. dennoch weißt du nicht", "℘ 1Sam 25,8"] },
      { number: 3, text: "Wenn die Wolken voll werden, gießen sie Regen aus auf die Erde. Und wenn ein Baum nach Süden oder nach Norden fällt: an der Stelle, wo der Baum fällt, da muss er liegen bleiben*.", footnotes: ["℘ Lk 16,26"] },
      { number: 4, text: "Wer auf den Wind achtet, wird nie säen, und wer auf die Wolken sieht, wird nie ernten*. —", footnotes: ["℘ Spr 20,4"] },
      { number: 5, text: "Wie du den Weg des Windes nicht kennst* und nicht die Gebeine im Leib der Schwangeren, so kennst du das Werk Gottes nicht, der alles wirkt*. —", footnotes: ["℘ Kap. 1,6; Joh 3,8", "℘ Kap. 3,11; Hi 26,14; Mk 4,27"] },
      { number: 6, text: "Am Morgen säe deinen Samen und am Abend lass deine Hand nicht ruhen! Denn du weißt nicht, was gedeihen wird: ob dieses oder jenes oder ob beides zugleich* gut werden wird*. —", footnotes: ["w. wie ein einziges", "℘ 1Kor 3,7"] },
      { number: 7, text: "Süß aber ist das Licht, und gut für die Augen ist es, die Sonne zu sehen*.", footnotes: ["℘ Kap. 12,2"] },
      { number: 8, text: "Denn wenn der Mensch viele Jahre lebt, soll er in ihnen allen sich freuen und an die Tage der Finsternis denken*, dass sie viel sein werden*. Alles, was kommt, ist Nichtigkeit.", footnotes: ["℘ Hi 10,21", "℘ Hi 14,12; Ps 49,20"] },
      { number: 9, text: "Freue dich, Jüngling, in deiner Jugend, und dein Herz mache dich fröhlich in den Tagen deiner Jugendzeit*! Und lebe nach dem, was dein Herz wünscht und wonach deine Augen ausschauen*! Doch wisse, dass um all dieser Dinge willen Gott dich zur Rechenschaft ziehen wird*!", heading: "Freuden der Jugend, Mühsale des Alters", footnotes: ["℘ Kap. 7,14", "w. Und geh auf den Wegen deines Herzens und im Sehen deiner Augen!", "℘ Kap. 3,12; 12,14"] },
      { number: 10, text: "Entferne den Unmut aus deinem Herzen und halte Übel von deinem Leib fern! Denn Jugend und dunkles Haar sind Nichtigkeit*.", footnotes: ["℘ Ps 39,6"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und denke an deinen Schöpfer* in den Tagen deiner Jugendzeit, bevor die Tage des Übels kommen und die Jahre herannahen, von denen du sagen wirst: Ich habe kein Gefallen an ihnen*! —", footnotes: ["℘ 5Mo 8,18", "℘ 2Sam 19,36"] },
      { number: 2, text: "bevor sich verfinstern die Sonne und das Licht*, der Mond und die Sterne, und die Wolken nach dem Regen wiederkehren;", footnotes: ["℘ Kap. 11,7"] },
      { number: 3, text: "an dem Tag, wenn die Wächter des Hauses zittern und die starken Männer sich krümmen und die Müllerinnen müßig gehen*, weil sie wenig geworden, wenn sich verfinstern, die durch die Fenster sehen*,", footnotes: ["o. frei von Arbeit sind; o. feiern", "℘ 1Mo 27,1"] },
      { number: 4, text: "und die Türen zur Straße hin geschlossen werden, während das Geräusch der Mühle dünner wird und ansteigt zur Vogelstimme*, und alle Töchter des Gesangs werden gedämpft.", footnotes: ["o. und man sich zur Zeit des Vogelgezwitschers erhebt"] },
      { number: 5, text: "Auch vor der Anhöhe fürchtet man sich, und Schrecknisse sind auf dem Weg. Und der Mandelbaum steht in Blüte*, und die Heuschrecke schleppt sich mühsam dahin*, und die Kaper platzt auf*. Denn der Mensch geht hin zu seinem ewigen Haus*, und die Klagenden ziehen umher auf der Straße*; —", footnotes: ["℘ Spr 16,31", "o. packt sich mit Fressen voll", "o. versagt", "℘ Hi 17,13", "℘ Jer 9,16"] },
      { number: 6, text: "bevor die silberne Schnur zerreißt* und die goldene Schale zerspringt* und der Krug am Quell zerbricht und das Schöpfrad zersprungen in den Brunnen fällt.", footnotes: ["so mit der Leseform des Mas. T.; mit der Schreibform: entfernt wird", "T.; Mas. T.: zersprengt"] },
      { number: 7, text: "Und der Staub kehrt zur Erde zurück, so wie er gewesen*, und der Geist kehrt zu Gott zurück*, der ihn gegeben hat.", footnotes: ["℘ Hi 34,15; Ps 90,3", "℘ Ps 31,6"] },
      { number: 8, text: "Nichtigkeit der Nichtigkeiten!, spricht der Prediger. Alles ist Nichtigkeit*!", footnotes: ["℘ Kap. 1,2.14"] },
      { number: 9, text: "Und darüber hinaus, dass der Prediger weise war, lehrte er noch das Volk Erkenntnis* und erwog und forschte und verfasste viele Sprüche*.", heading: "Die Summe aller Lehre: Gottesfurcht", footnotes: ["℘ Dan 12,3", "℘ 1Kö 5,12; Spr 1,1"] },
      { number: 10, text: "Der Prediger suchte, wohlgefällige Worte zu finden* und Worte der Wahrheit aufrichtig niederzuschreiben*.", footnotes: ["℘ Spr 16,24", "so mit 5 hebr. Handschr.; mehrere alte Üs.: und er schrieb Richtiges, Worte der Wahrheit; Mas. T.: und in Aufrichtigkeit Niedergeschriebenes, Worte der Wahrheit\n℘ Spr 1,3"] },
      { number: 11, text: "Die Worte der Weisen sind wie Treiberstachel und wie eingeschlagene Nägel die gesammelten Sprüche*. Sie sind gegeben von einem Hirten*.", footnotes: ["w. Herren der Sammlungen", "℘ Spr 10,21"] },
      { number: 12, text: "Und darüber hinaus, mein Sohn, lass dich von ihnen warnen! Des vielen Büchermachens ist kein Ende, und viel Studieren ermüdet den Leib*.", footnotes: ["w. das Fleisch\n℘ Kap. 1,18"] },
      { number: 13, text: "Das Endergebnis des Ganzen* lasst uns hören: Fürchte Gott* und halte seine Gebote*! Denn das soll jeder Mensch tun*.", footnotes: ["w. Das Ende der Sache o. der Rede", "℘ Kap. 3,14; 5Mo 4,10; 10,12; 1Petr 2,17", "℘ 1Kö 2,3; 1Kor 7,19", "o. das ist der ganze Mensch"] },
      { number: 14, text: "Denn Gott wird jedes Werk, es sei gut oder böse, in ein Gericht über alles Verborgene bringen*.", footnotes: ["℘ Kap. 3,17; 11,9; Ps 50,21; Mt 12,36; Röm 2,16; 14,10; 2Kor 5,10"] },
    ]},
  ]
};
